-- 23 empresas
insert into empresas (slug, marca, razon_social, estado, municipio, sector, resumen_es, resumen_en, descripcion_es, descripcion_en, destacado_es, destacado_en, exporta_desde, situacion, maquila, abv, productos, presentaciones_ml, contacto_email, contacto_tel, estatus, fuente)
values ('calten-group', 'Calten Group', null, 'puebla', 'San Pedro Cholula', 'logistica-comercio-exterior', 'Logística, comercio exterior e inspección en origen para pymes que no tienen un departamento de operaciones internacionales.', 'Logistics, foreign trade and inspection at origin for SMEs without an in-house international operations team.', 'Calten Group acompaña a pequeñas y medianas empresas que importan o exportan sin tener un departamento de operaciones internacionales. Con más de 18 años de experiencia, integra logística internacional, gestión aduanera, transporte nacional y coordinación de embarques, ya sea por operación o como equipo in-house por contrato, y actúa también como comercializadora.

En comercio exterior arma y revisa expedientes, gestiona trámites ante la VUCEM, asesora en importación y exportación, en el cumplimiento de NOMs y en certificaciones IMMEX y PROSEC, y ayuda a calcular el costo y precio de productos internacionales. Además ofrece inspección en origen —auditoría de fábrica, control de calidad e inspección previa al embarque—, seguros de carga nacional e internacional y cursos de comercio exterior, básicos o a la medida.', 'Calten Group supports small and medium-sized companies that import or export without an international operations department. With more than 18 years of experience, it combines international logistics, customs management, domestic transport and shipment coordination — per operation or as an in-house team on a time-based contract — and also acts as a trading company.

In foreign trade, it prepares and reviews compliance files, handles procedures on Mexico''s VUCEM single window, advises on imports and exports, Mexican Official Standards (NOMs) and IMMEX and PROSEC certification, and helps cost and price international products. It also offers inspection at origin — factory audits, quality control and pre-shipment inspection — domestic and international cargo insurance, and foreign trade courses, from basics to custom programmes.', 'Inspección de calidad en origen', 'Quality inspection at origin', null, 'sin_dato', null, null, array['Logística internacional y transporte nacional', 'Gestión aduanera', 'Coordinación de embarques (por operación o in-house)', 'Expedientes de comercio exterior y trámites VUCEM', 'Certificaciones IMMEX y PROSEC', 'Asesoría en NOMs', 'Costeo y pricing de productos internacionales', 'Inspección en origen: auditoría de fábrica y control de calidad', 'Seguros de carga nacional e internacional', 'Cursos de comercio exterior']::text[], '{}'::integer[], 'emma.perez@caltengroup.com', '+52 222 455 3621', 'borrador', 'Directorio de Socios COMCE Sur 2026')
on conflict (slug) do nothing;

insert into empresas (slug, marca, razon_social, estado, municipio, sector, resumen_es, resumen_en, descripcion_es, descripcion_en, destacado_es, destacado_en, exporta_desde, situacion, maquila, abv, productos, presentaciones_ml, contacto_email, contacto_tel, estatus, fuente)
values ('cashabroad', 'CashAbroad', null, 'ciudad-de-mexico', null, 'pagos-internacionales', 'Pagos a proveedores internacionales con dólares digitales (USDC) para exportadores e importadores que operan entre México, Estados Unidos y China.', 'Supplier payments abroad with digital dollars (USDC) for exporters and importers trading between Mexico, the United States and China.', 'CashAbroad es una plataforma de tesorería empresarial para exportadores e importadores que operan entre México, Estados Unidos y China. Con una cuenta en dólares digitales (USDC, con paridad 1:1 con el dólar), las empresas pagan a proveedores y reciben cobros de clientes en el extranjero en unas cuatro horas —en lugar de los días que toma una transferencia tradicional—, deciden cuándo convertir y liquidan en moneda local mediante socios bancarios en más de ocho países.

La cuenta se activa en menos de 48 horas, no cobra anualidad y funciona junto a las cuentas bancarias que la empresa ya usa. Opera sobre las blockchains Stellar y Starknet, con procesos KYB/KYC, prevención de lavado de dinero y monitoreo de transacciones alineados con los requisitos del SAT para actividades vulnerables, y ofrece acompañamiento para configurar cada flujo (Business Concierge). Cuenta con el respaldo de Techstars y Draper University.', 'CashAbroad is a corporate treasury platform for exporters and importers trading between Mexico, the United States and China. With an account in digital dollars (USDC, pegged 1:1 to the US dollar), companies pay suppliers and collect from customers abroad in about four hours — instead of the days a traditional wire takes — decide when to convert, and settle in local currency through banking partners in more than eight countries.

Accounts are activated in under 48 hours, with no annual fee, and work alongside the bank accounts a company already uses. It runs on the Stellar and Starknet blockchains, with KYB/KYC, anti-money-laundering and transaction-monitoring processes aligned with Mexican tax authority (SAT) requirements for vulnerable activities, and offers hands-on support to set up each flow (Business Concierge). It is backed by Techstars and Draper University.', 'Pagos internacionales en 4 horas', 'International payments in 4 hours', null, 'sin_dato', null, null, array['Cuenta empresarial en dólares digitales (USDC)', 'Pagos a proveedores en México, Estados Unidos y China', 'Cobros de clientes en el extranjero', 'Conversión a moneda local y salida bancaria en más de 8 países', 'Tesorería con stablecoins', 'Business Concierge: configuración de flujos financieros']::text[], '{}'::integer[], 'ruth@cashabroad.one', '+52 55 8046 5994', 'borrador', 'Directorio de Socios COMCE Sur 2026')
on conflict (slug) do nothing;

insert into empresas (slug, marca, razon_social, estado, municipio, sector, resumen_es, resumen_en, descripcion_es, descripcion_en, destacado_es, destacado_en, exporta_desde, situacion, maquila, abv, productos, presentaciones_ml, contacto_email, contacto_tel, estatus, fuente)
values ('cogne-mexico', 'COGNE México', null, 'tlaxcala', 'Huamantla', 'productos-metalicos', 'Alambre y barras de acero inoxidable y aleaciones de níquel fabricados en Huamantla, Tlaxcala, por la planta mexicana del grupo italiano Cogne. Exporta a Estados Unidos y Europa.', 'Stainless steel and nickel alloy wire and bars made in Huamantla, Tlaxcala, by the Mexican plant of Italy''s Cogne Group. Exports to the United States and Europe.', 'COGNE México —antes Trefilados Inoxidables de México (TIM)— es la planta mexicana del grupo Cogne Acciai Speciali, con sede en Aosta, Italia, y más de un siglo de historia, líder mundial en productos largos de acero inoxidable y aleaciones de níquel. Su planta en la Ciudad Industrial Xicohténcatl II de Huamantla, Tlaxcala, ocupa un terreno de 36,500 m² con 13,000 m² de naves, oficinas y laboratorios, y cuenta con certificaciones ISO 9001, IATF 16949 para la industria automotriz, ISO 14001 e Industria Limpia.

Fabrica alambre de acero inoxidable y de aleaciones de níquel de 0.15 a 10 mm —fino, para resortes, para forja en frío, planos y perfiles especiales— en rollos, botes y carretes; barras de acero inoxidable de 3 a 20 mm y barras rectificadas sin centros de 6 a 31.5 mm, con maquila de rectificado desde una tonelada e inspección por corrientes de Eddy y ultrasonido. También ofrece soldaduras especiales de acero inoxidable, níquel y aluminio, y acero para válvulas automotrices. Exporta a Estados Unidos, Europa y Centro y Sudamérica, y opera con los programas IMMEX, ALTEX y PROSEC y como Operador Económico Autorizado.', 'COGNE México — formerly Trefilados Inoxidables de México (TIM) — is the Mexican plant of the Cogne Acciai Speciali group, headquartered in Aosta, Italy, with more than a century of history and a world leader in long stainless steel and nickel alloy products. Its plant in the Xicohténcatl II Industrial City in Huamantla, Tlaxcala, sits on a 36,500 m² site with 13,000 m² of production halls, offices and laboratories, and is certified to ISO 9001, IATF 16949 for the automotive industry, ISO 14001 and Mexico''s Clean Industry programme.

It makes stainless steel and nickel alloy wire from 0.15 to 10 mm — fine, spring, cold-heading, flat and special-profile wire — on coils, drums and spools; stainless steel bars from 3 to 20 mm and centreless-ground bars from 6 to 31.5 mm, with toll grinding from one tonne and eddy-current and ultrasonic inspection. It also supplies special stainless steel, nickel and aluminium welding wire, and automotive valve steel. It exports to the United States, Europe and Central and South America, and operates under Mexico''s IMMEX, ALTEX and PROSEC programmes and as an Authorised Economic Operator.', 'Planta del grupo italiano Cogne', 'Plant of Italy''s Cogne Group', null, 'exportando', null, null, array['Alambre de acero inoxidable de 0.15 a 10 mm', 'Alambre de aleaciones de níquel', 'Alambre para resortes', 'Alambre para forja en frío', 'Alambres planos y perfiles especiales', 'Barras de acero inoxidable de 3 a 20 mm', 'Barras rectificadas sin centros (6 a 31.5 mm)', 'Maquila de rectificado desde 1 tonelada', 'Soldaduras especiales de inoxidable, níquel y aluminio', 'Acero para válvulas automotrices']::text[], '{}'::integer[], 'mcastillo@cogne.com.mx', null, 'borrador', 'Directorio de Socios COMCE Sur 2026')
on conflict (slug) do nothing;
insert into empresa_mercados (empresa_id, pais) select id, 'estados-unidos' from empresas where slug = 'cogne-mexico' on conflict do nothing;

