values ('cslogix', 'CsLogix', null, 'puebla', 'Puebla', 'logistica-comercio-exterior', 'Estrategias y soluciones logísticas para comercio internacional y transporte nacional.', 'Logistics strategies and solutions for international trade and domestic transport.', 'CsLogix diseña estrategias y soluciones para operaciones de comercio internacional y logística de transporte nacional. Su trabajo se centra en optimizar procesos, mejorar la coordinación de las cadenas de suministro y facilitar el movimiento eficiente de mercancías, con servicios adaptados a cada cliente.', 'CsLogix designs strategies and solutions for international trade operations and domestic transport logistics. Its work focuses on optimising processes, improving supply chain coordination and moving goods efficiently, with services tailored to each client.', 'Logística nacional e internacional', 'Domestic and international logistics', null, 'sin_dato', null, null, array['Logística internacional', 'Transporte nacional', 'Coordinación de cadena de suministro']::text[], '{}'::integer[], 'nohemi.camberos@cslogix.com', null, 'borrador', 'Directorio de Socios COMCE Sur 2026')
