values ('fairwind-group', 'FairWind Group', null, 'puebla', 'Puebla', 'logistica-comercio-exterior', 'Soluciones de comercio exterior, logística internacional y gestión operativa para crecer en mercados globales.', 'Foreign trade, international logistics and operations management solutions for growing in global markets.', 'FairWind integra servicios de comercio exterior, logística internacional y gestión operativa para empresas que buscan crecer en mercados globales. Con más de 10 años de experiencia, ofrece logística nacional e internacional, consultoría en exportación e importación, búsqueda de proveedores y clientes en el extranjero, gestión aduanera, capacitación y software para controlar operaciones de comercio exterior.', 'FairWind brings together foreign trade, international logistics and operations management services for companies looking to grow in global markets. With more than 10 years of experience, it offers domestic and international logistics, export and import consulting, sourcing of suppliers and customers abroad, customs management, training and software to manage foreign trade operations.', 'Software para comercio exterior', 'Foreign trade software', null, 'sin_dato', null, null, array['Logística nacional e internacional', 'Consultoría en exportación e importación', 'Búsqueda de proveedores y clientes', 'Gestión aduanera', 'Capacitación', 'Software de comercio exterior']::text[], '{}'::integer[], 'jesus.hernandez@fairwind.mx', null, 'borrador', 'Directorio de Socios COMCE Sur 2026')
on conflict (slug) do nothing;

