insert into empresas (slug, marca, razon_social, estado, municipio, sector, resumen_es, resumen_en, descripcion_es, descripcion_en, destacado_es, destacado_en, exporta_desde, situacion, maquila, abv, productos, presentaciones_ml, contacto_email, contacto_tel, estatus, fuente)
values ('amp-solutions', 'Grupo AMP Solutions', null, 'ciudad-de-mexico', 'Cuauhtémoc', 'logistica-comercio-exterior', 'Logística integral y asesoría en comercio exterior: despacho aduanal, fletes marítimo y terrestre, almacenaje y Recinto Fiscalizado Estratégico (RFE).', 'End-to-end logistics and foreign trade advice: customs clearance, sea and road freight, warehousing and Strategic Bonded Zone (RFE) services.', 'Grupo AMP Solutions integra en un solo servicio la cadena logística de importación y exportación: flete marítimo y terrestre, despacho aduanal, almacenaje, maniobras y seguro de mercancías. Trabaja con agentes aduanales aliados en las principales aduanas del país —Manzanillo, Lázaro Cárdenas, Veracruz, el AICM, Pantaco y el Aeropuerto de Guadalajara— y maneja alrededor de 250 despachos al mes y 75,000 toneladas de carga al año.

Mueve contenedor completo (FCL), carga consolidada (LCL), refrigerada, de proyecto, sobredimensionada y mercancía peligrosa, con unidades con rastreo GPS las 24 horas y custodia en carretera. Cuenta con 1,500 m² de almacén techado y 4,200 m² de bodega con vigilancia por circuito cerrado, y ofrece Recinto Fiscalizado Estratégico (RFE), depósito fiscal, oficina IMMEX, certificación de IVA e IEPS y clasificación arancelaria. Atiende sobre todo a las industrias de maquinaria pesada, acero, automotriz, equipo médico, química, calzado, textil y electrónica.', 'Grupo AMP Solutions brings the whole import and export logistics chain into a single service: sea and road freight, customs clearance, warehousing, cargo handling and cargo insurance. It works with partner customs brokers at Mexico''s main customs points — Manzanillo, Lázaro Cárdenas, Veracruz, Mexico City International Airport, Pantaco and Guadalajara Airport — and handles around 250 customs clearances a month and 75,000 tonnes of cargo a year.

It moves full container loads (FCL), less-than-container loads (LCL), refrigerated, project, oversized and dangerous cargo, with 24/7 GPS-tracked trucks and road escort. It has 1,500 m² of covered warehouse and 4,200 m² of storage with CCTV surveillance, and offers Strategic Bonded Zone (RFE) and bonded warehouse services, an IMMEX office, VAT and IEPS certification, and tariff classification. It mainly serves the heavy machinery, steel, automotive, medical equipment, chemical, footwear, textile and electronics industries.', '250 despachos aduanales al mes', '250 customs clearances a month', null, 'sin_dato', null, null, array['Despacho aduanal de importación y exportación', 'Flete marítimo: FCL, LCL, refrigerado y carga de proyecto', 'Flete terrestre con rastreo GPS y custodia', 'Almacenaje, consolidación y desconsolidación', 'Recinto Fiscalizado Estratégico (RFE) y depósito fiscal', 'Oficina IMMEX', 'Certificación de IVA e IEPS', 'Clasificación arancelaria y control de permisos', 'Seguro de mercancías', 'Mercancía peligrosa y carga sobredimensionada']::text[], '{}'::integer[], 'rcareaga@grupoamp.mx', '+52 314 146 2708', 'borrador', 'Directorio de Socios COMCE Sur 2026')
on conflict (slug) do nothing;

insert into empresas (slug, marca, razon_social, estado, municipio, sector, resumen_es, resumen_en, descripcion_es, descripcion_en, destacado_es, destacado_en, exporta_desde, situacion, maquila, abv, productos, presentaciones_ml, contacto_email, contacto_tel, estatus, fuente)
values ('grupo-ravara', 'Grupo RAVARA', null, 'nuevo-leon', 'García', 'cosmetica', 'Centro tecnológico que diseña y fabrica ingredientes activos para cosmética y cuidado personal.', 'Technology centre that designs and manufactures active ingredients for cosmetics and personal care.', 'Grupo RAVARA es un centro tecnológico mexicano que diseña y manufactura ingredientes activos para las industrias cosmética, de cuidado personal, del hogar y capilar. Combina ciencia y herbolaria tradicional para desarrollar extractos botánicos, proteínas, péptidos y complejos activos con funciones de hidratación, antienvejecimiento, protección capilar, regeneración celular, control antimicrobiano y protección contra la contaminación.', 'Grupo RAVARA is a Mexican technology centre that designs and manufactures active ingredients for the cosmetics, personal care, home care and hair care industries. It combines science with traditional herbal knowledge to develop botanical extracts, proteins, peptides and active complexes for hydration, anti-ageing, hair protection, cell renewal, antimicrobial control and protection against pollution.', 'Ingredientes de origen natural', 'Naturally derived ingredients', null, 'sin_dato', null, null, array['Extractos botánicos', 'Proteínas y péptidos', 'Complejos activos', 'Activos para cuidado capilar', 'Formulaciones a la medida']::text[], '{}'::integer[], 'alejandra@gruporavara.com', null, 'borrador', 'Directorio de Socios COMCE Sur 2026')
on conflict (slug) do nothing;

