values ('lari-moda', 'LARI MODA', null, 'oaxaca', null, 'textil-y-confeccion', 'Prendas bordadas a mano por mujeres artesanas, con telas y procesos conscientes.', 'Garments hand-embroidered by women artisans, using mindful fabrics and processes.', 'LARI MODA crea prendas bordadas a mano por mujeres artesanas en pequeños talleres comunitarios, con telas más amigables con la naturaleza. Su modelo impulsa el empoderamiento económico de las mujeres, preserva técnicas tradicionales de bordado y promueve una moda ética, con piezas atemporales pensadas para durar.', 'LARI MODA makes garments hand-embroidered by women artisans in small community workshops, using more environmentally friendly fabrics. Its model supports women''s economic empowerment, preserves traditional embroidery techniques and promotes ethical fashion, with timeless pieces made to last.', 'Bordado artesanal', 'Hand embroidery', null, 'sin_dato', null, null, array['Prendas bordadas a mano', 'Moda sostenible']::text[], '{}'::integer[], 'oly@larimoda.mx', null, 'borrador', 'Directorio de Socios COMCE Sur 2026')
on conflict (slug) do nothing;

insert into empresas (slug, marca, razon_social, estado, municipio, sector, resumen_es, resumen_en, descripcion_es, descripcion_en, destacado_es, destacado_en, exporta_desde, situacion, maquila, abv, productos, presentaciones_ml, contacto_email, contacto_tel, estatus, fuente)
values ('licorera-del-sur', 'Licorera del Sur', null, 'oaxaca', 'Santiago Matatlán', 'bebidas-espirituosas', 'Productora y distribuidora de bebidas espirituosas de Santiago Matatlán, Oaxaca, con más de 40 años de experiencia.', 'Spirits producer and distributor from Santiago Matatlán, Oaxaca, with more than 40 years of experience.', 'Licorera del Sur produce y distribuye bebidas espirituosas desde Santiago Matatlán, Oaxaca, una de las regiones con mayor tradición mezcalera del país. Con más de 40 años de experiencia y productos galardonados, cuenta con capacidad propia de fabricación, embotellado, etiquetado y distribución.', 'Licorera del Sur produces and distributes spirits from Santiago Matatlán, Oaxaca, one of Mexico''s most traditional mezcal regions. With more than 40 years of experience and award-winning products, it has its own production, bottling, labelling and distribution capacity.', '40 años de trayectoria', '40 years in business', null, 'sin_dato', null, null, array['Bebidas espirituosas']::text[], '{}'::integer[], 'jrodriguez@licoreradelsur.com', null, 'borrador', 'Directorio de Socios COMCE Sur 2026')
on conflict (slug) do nothing;

