values ('mezcal-capotlan', 'Mezcal Capotlán', null, 'oaxaca', 'Las Razas', 'destilados-de-agave', 'Mezcal artesanal oaxaqueño de agaves Espadín, Tobalá y Tepeztate.', 'Artisanal mezcal from Oaxaca made from Espadín, Tobalá and Tepeztate agaves.', 'Mezcal Capotlán elabora y promueve mezcal artesanal de alta calidad con métodos tradicionales de producción. Sus destilados expresan el carácter de cada variedad de agave —Espadín, Tobalá y Tepeztate— y la riqueza cultural, los aromas y sabores de Oaxaca.', 'Mezcal Capotlán makes and promotes high-quality artisanal mezcal using traditional production methods. Its spirits express the character of each agave variety — Espadín, Tobalá and Tepeztate — and the cultural richness, aromas and flavours of Oaxaca.', 'Mezcal artesanal', 'Artisanal mezcal', null, 'sin_dato', null, null, array['Espadín', 'Tobalá', 'Tepeztate']::text[], '{}'::integer[], 'mezcalcapotlan@gmail.com', null, 'borrador', 'Directorio de Socios COMCE Sur 2026')
on conflict (slug) do nothing;

