values ('mezcal-dolores', 'Mezcal Dolores', null, 'oaxaca', 'Santiago Matatlán', 'destilados-de-agave', 'Mezcal artesanal de Santiago Matatlán elaborado con procesos tradicionales.', 'Artisanal mezcal from Santiago Matatlán made with traditional processes.', 'Mezcal Dolores produce y comercializa mezcal artesanal cuidando cada etapa del proceso tradicional, para ofrecer destilados auténticos, con identidad y carácter propio, dirigidos al mercado nacional e internacional.', 'Mezcal Dolores produces and sells artisanal mezcal, taking care of every stage of the traditional process to offer authentic spirits with their own identity and character for domestic and international markets.', 'Mezcal artesanal', 'Artisanal mezcal', null, 'sin_dato', null, null, array['Mezcal artesanal']::text[], '{}'::integer[], 'marilyn.dolores30@gmail.com', null, 'borrador', 'Directorio de Socios COMCE Sur 2026')
on conflict (slug) do nothing;

