values ('mezcal-la-entrega', 'Mezcal La Entrega', null, 'oaxaca', 'Oaxaca de Juárez', 'destilados-de-agave', 'Mezcal artesanal 100% orgánico, destilado en alambique de cobre.', '100% organic artisanal mezcal distilled in copper stills.', 'Mezcal La Entrega produce mezcal artesanal 100% orgánico con procesos tradicionales: agaves maduros cocidos en hornos de piedra subterráneos, fermentación natural en tinas de madera y destilación en alambique de cobre. El resultado es un destilado puro, complejo y con el ahumado característico del mezcal.', 'Mezcal La Entrega produces 100% organic artisanal mezcal using traditional methods: mature agaves cooked in underground stone ovens, natural fermentation in wooden vats and distillation in copper stills. The result is a pure, complex spirit with mezcal''s characteristic smokiness.', '100% orgánico', '100% organic', null, 'sin_dato', null, null, array['Mezcal artesanal orgánico']::text[], '{}'::integer[], 'laentregamezcal@gmail.com', null, 'borrador', 'Directorio de Socios COMCE Sur 2026')
on conflict (slug) do nothing;

