values ('multilog-internacional', 'Multilog Internacional', null, 'ciudad-de-mexico', null, 'logistica-comercio-exterior', 'Logística y cadena de suministro: transporte terrestre, aéreo y marítimo, almacenaje y distribución.', 'Logistics and supply chain: road, air and sea freight, warehousing and distribution.', 'Multilog Internacional ofrece desde hace más de 16 años soluciones integrales de logística y cadena de suministro para empresas de distintos sectores. Integra transporte terrestre, aéreo y marítimo, almacenamiento, distribución y operaciones in-house bajo un mismo esquema, con atención personalizada.', 'For more than 16 years, Multilog Internacional has provided end-to-end logistics and supply chain solutions for companies in different sectors. It combines road, air and sea freight, warehousing, distribution and in-house operations under a single scheme, with personalised service.', '16 años en logística', '16 years in logistics', null, 'sin_dato', null, null, array['Transporte terrestre', 'Transporte aéreo', 'Transporte marítimo', 'Almacenamiento', 'Distribución', 'Operaciones in-house']::text[], '{}'::integer[], 'orlando.vazquez@multilog.com.mx', null, 'borrador', 'Directorio de Socios COMCE Sur 2026')
on conflict (slug) do nothing;

