values ('oceamar', 'Oceamar', null, 'campeche', 'Ciudad del Carmen', 'logistica-comercio-exterior', 'Agencia de logística offshore para la industria marítima y petrolera.', 'Offshore logistics agency for the maritime and oil industries.', 'Oceamar (Ocean Marine) es una agencia de logística integral offshore que atiende a la industria marítima y petrolera. Coordina soluciones logísticas, operativas y de soporte para operaciones costa afuera, con foco en eficiencia, seguridad y cumplimiento en proyectos del sector energético.', 'Oceamar (Ocean Marine) is an end-to-end offshore logistics agency serving the maritime and oil industries. It coordinates logistics, operational and support solutions for offshore operations, focusing on efficiency, safety and compliance in energy sector projects.', 'Logística offshore', 'Offshore logistics', null, 'sin_dato', null, null, array['Logística offshore', 'Soporte a operaciones costa afuera', 'Servicios a la industria marítima y petrolera']::text[], '{}'::integer[], 'enrique.escobar@oceamar.com', null, 'borrador', 'Directorio de Socios COMCE Sur 2026')
on conflict (slug) do nothing;

