values ('pilu-uniformes', 'Pilu Uniformes', null, 'puebla', 'Puebla', 'textil-y-confeccion', 'Diseño y fabricación de uniformes industriales e institucionales.', 'Design and manufacture of industrial and corporate uniforms.', 'Pilu Uniformes Industriales de México diseña, fabrica y comercializa uniformes industriales e institucionales adaptados a cada organización. Combina imagen corporativa, ergonomía y seguridad en prendas funcionales y de alta calidad.', 'Pilu Uniformes Industriales de México designs, manufactures and sells industrial and corporate uniforms tailored to each organisation. It combines corporate image, ergonomics and safety in functional, high-quality garments.', 'Uniformes a la medida', 'Made-to-order uniforms', null, 'sin_dato', null, null, array['Uniformes industriales', 'Uniformes institucionales']::text[], '{}'::integer[], 'eduardosanchez@piluniformes.com.mx', null, 'borrador', 'Directorio de Socios COMCE Sur 2026')
on conflict (slug) do nothing;

