values ('las-vegas-premium-limes', 'Las Vegas Premium Limes', 'Productos Men-Frut S.A. de C.V.', 'veracruz', 'Martínez de la Torre', 'frutas-y-hortalizas', 'Empaque y exportación de lima persa de alta calidad durante todo el año.', 'Packing and export of high-quality Persian limes all year round.', 'Productos Men-Frut empaca y exporta lima persa bajo la marca Las Vegas Premium Limes desde Martínez de la Torre, Veracruz, una de las regiones citrícolas más importantes de México. Ofrece producto fresco todo el año y cumple estándares internacionales para abastecer mercados alrededor del mundo.', 'Productos Men-Frut packs and exports Persian limes under the Las Vegas Premium Limes brand from Martínez de la Torre, Veracruz, one of Mexico''s leading citrus regions. It supplies fresh product all year round and meets international standards to serve markets around the world.', 'Lima persa todo el año', 'Persian limes all year round', null, 'exportando', null, null, array['Lima persa']::text[], '{}'::integer[], 'hugo.mendez@citru-mex.com.mx', null, 'borrador', 'Directorio de Socios COMCE Sur 2026')
on conflict (slug) do nothing;

insert into empresas (slug, marca, razon_social, estado, municipio, sector, resumen_es, resumen_en, descripcion_es, descripcion_en, destacado_es, destacado_en, exporta_desde, situacion, maquila, abv, productos, presentaciones_ml, contacto_email, contacto_tel, estatus, fuente)
values ('recodding', 'Recodding', null, 'puebla', 'Puebla', 'tecnologia', 'Automatización con agentes de inteligencia artificial para los procesos operativos de las empresas: conciliación, aprobaciones, cotizaciones y reportes.', 'AI agent automation for companies'' operational processes: reconciliation, approvals, quotes and reporting.', 'Recodding construye agentes de automatización a la medida que ejecutan los flujos de trabajo operativos de una empresa —aprobaciones, conciliación de facturas, reportes, cotizaciones, clasificación de solicitudes o el paso de pedidos entre sistemas—: el trabajo que antes se hacía a mano, para que se complete en minutos en lugar de días. Cada agente se diseña para un proceso específico y se conecta a los sistemas que la empresa ya usa.

Su método avanza por etapas: primero mapea el proceso tal como lo ejecuta el equipo; después construye el agente y lo pone a trabajar en paralelo con revisión humana en cada decisión, y solo cuando su precisión se comprueba con volumen real asume el proceso completo, con registro de auditoría y una persona que puede intervenir ante cualquier excepción. Atiende a empresas de servicios financieros, manufactura, logística y cadena de suministro, comercio electrónico, salud, seguros y servicios profesionales.', 'Recodding builds custom automation agents that run a company''s operational workflows — approvals, invoice reconciliation, reporting, quotes, request triage or moving orders between systems: work that used to be done by hand, so it gets done in minutes instead of days. Each agent is designed for a specific process and connects to the systems the company already uses.

Its method works in stages: first it maps the process as the team actually runs it; then it builds the agent and runs it in parallel with human review of every decision, and only once its accuracy is proven on real volume does it take over the whole process, with a full audit trail and a person who can step in on any exception. It serves companies in financial services, manufacturing, logistics and supply chain, e-commerce, healthcare, insurance and professional services.', 'Agentes de IA con supervisión humana', 'AI agents with human oversight', null, 'sin_dato', null, null, array['Agentes de automatización a la medida', 'Conciliación de facturas y cuentas por pagar', 'Flujo de pedidos entre sistemas', 'Cotizaciones y contratos desde el CRM', 'Clasificación y enrutamiento de solicitudes', 'Reportes y datos entre aplicaciones']::text[], '{}'::integer[], 'eduardo@recodding.com', null, 'borrador', 'Directorio de Socios COMCE Sur 2026')
on conflict (slug) do nothing;

insert into empresas (slug, marca, razon_social, estado, municipio, sector, resumen_es, resumen_en, descripcion_es, descripcion_en, destacado_es, destacado_en, exporta_desde, situacion, maquila, abv, productos, presentaciones_ml, contacto_email, contacto_tel, estatus, fuente)
values ('saeta', 'SAETA Orientación Corporativa', null, 'puebla', 'San Andrés Cholula', 'consultoria', 'Consultoría integral para empresas mexicanas y extranjeras: comercio exterior e IMMEX, contabilidad, legal, nómina y softlanding, en español, inglés y alemán.', 'All-in-one consulting for Mexican and foreign companies: foreign trade and IMMEX, accounting, legal, payroll and soft landing, in Spanish, English and German.', 'SAETA Orientación Corporativa es una firma de consultoría que reúne bajo un mismo techo siete áreas de servicio —softlanding, legal, contabilidad, fiscal, nómina y tesorería, comercio exterior y auditoría— para descomplicar los procesos corporativos de sus clientes. Fundada en 2022, atiende a más de 60 empresas nacionales e internacionales desde sus oficinas en Puebla y en el German Centre de la Ciudad de México.

En comercio exterior acompaña a las empresas en el programa IMMEX, el cumplimiento de NOMs y permisos de COFEPRIS y SEDENA, auditorías con Data Stage y de los Anexos 24 y 30, reglas de origen, devolución de IVA y la coordinación de la logística y el despacho aduanal. Trabaja en español, inglés y alemán, y acompaña a empresas extranjeras, incluidas las de habla alemana, en su llegada a México.', 'SAETA Orientación Corporativa is a consulting firm that brings seven service areas under one roof — soft landing, legal, accounting, tax, payroll and treasury, foreign trade and auditing — to simplify its clients'' corporate processes. Founded in 2022, it serves more than 60 Mexican and international companies from its offices in Puebla and at the German Centre in Mexico City.

In foreign trade, it supports companies with the IMMEX programme, compliance with Mexican Official Standards (NOMs) and COFEPRIS and SEDENA permits, Data Stage audits and Annex 24 and 30 reviews, rules of origin, VAT refunds, and coordination of logistics and customs clearance. It works in Spanish, English and German, and helps foreign companies, including German-speaking ones, set up in Mexico.', 'Atiende en español, inglés y alemán', 'Service in Spanish, English and German', 2022, 'sin_dato', null, null, array['Softlanding para empresas extranjeras', 'Programa IMMEX', 'NOMs y permisos COFEPRIS y SEDENA', 'Auditoría de comercio exterior (Data Stage, Anexos 24 y 30)', 'Consultoría aduanera y reglas de origen', 'Coordinación logística y aduanal', 'Contabilidad, controlling y fiscal', 'Nómina y tesorería', 'Derecho corporativo, laboral y mercantil', 'Trámites migratorios', 'Registro de marcas']::text[], '{}'::integer[], 'eduardo.lopez@saetaoc.com', '+52 222 533 9586', 'borrador', 'Directorio de Socios COMCE Sur 2026')
on conflict (slug) do nothing;

insert into empresas (slug, marca, razon_social, estado, municipio, sector, resumen_es, resumen_en, descripcion_es, descripcion_en, destacado_es, destacado_en, exporta_desde, situacion, maquila, abv, productos, presentaciones_ml, contacto_email, contacto_tel, estatus, fuente)
values ('solferino-native', 'Solferino Native', null, 'quintana-roo', 'Solferino', 'bebidas-espirituosas', 'Primera destilería de Quintana Roo: gin artesanal con botánicos de la selva maya, medalla de oro como Mejor Gin de México en los World Gin Awards 2025.', 'Quintana Roo''s first distillery: craft gin with Mayan jungle botanicals, awarded gold as Best Mexican Gin at the World Gin Awards 2025.', 'Solferino Native es la primera destilería de Quintana Roo. Nació en 2020 en Solferino, un poblado de la selva maya camino a Holbox, y elabora gin y licores artesanales en alambique de cobre, en microlotes de máximo 120 botellas. Sus botánicos —zacate limón, hierbabuena, hoja santa, pimienta negra, romero y piel de toronja— se recolectan frescos con los vecinos del pueblo y se suman al enebro, el regaliz y la canela, sin químicos ni conservadores.

Su Dry Gin ganó la medalla de oro como Mejor Gin de México en los World Gin Awards 2025, en Reino Unido, donde quedó entre los seis mejores del mundo en la categoría Contemporary Style, y volvió a ser reconocido en la edición 2026. Suma oro en Cata d''Or World Spirits Awards (Chile, 2021 y 2025), plata en Las Vegas Global Spirit Awards 2025 y Gran Oro en el Concurso de Espirituosos de Guanajuato, y es miembro de The Gin Guild de Londres. Se vende en Quintana Roo, Ciudad de México, Estado de México, Querétaro y Baja California, en las tiendas La Europea de todo el país y en Amazon y Mercado Libre.', 'Solferino Native is Quintana Roo''s first distillery. It was founded in 2020 in Solferino, a village in the Mayan jungle on the way to Holbox, and makes craft gin and liqueurs in copper stills, in micro-batches of no more than 120 bottles. Its botanicals — lemongrass, spearmint, hoja santa, black pepper, rosemary and grapefruit peel — are gathered fresh with local villagers and added to juniper, liquorice and cinnamon, with no chemicals or preservatives.

Its Dry Gin won gold as Best Mexican Gin at the World Gin Awards 2025 in the United Kingdom, where it ranked among the world''s top six in the Contemporary Style category, and was recognised again in the 2026 edition. It also holds gold at the Cata d''Or World Spirits Awards (Chile, 2021 and 2025), silver at the Las Vegas Global Spirit Awards 2025 and Grand Gold at the Guanajuato Spirits Competition, and is a member of The Gin Guild in London. It is sold in Quintana Roo, Mexico City, the State of Mexico, Querétaro and Baja California, in La Europea stores nationwide, and on Amazon and Mercado Libre.', 'Oro · World Gin Awards 2025', 'Gold · World Gin Awards 2025', null, 'sin_dato', null, '30–55%', array['Solferino Native Dry Gin · 40% Alc. · 750 ml', 'Solferino Native Overproof Edition · gin 55% Alc.', 'Solferino Native Flair Edition · gin para bartenders de flair', 'Solferino Native Absenta · 55% Alc.', 'Balam · licor cítrico de zacate limón, naranja y toronja', 'Pancheel · licor de yaka · 30% Alc.']::text[], array[750]::integer[], 'info@solferinogin.com', null, 'borrador', 'Directorio de Socios COMCE Sur 2026')
on conflict (slug) do nothing;

insert into empresas (slug, marca, razon_social, estado, municipio, sector, resumen_es, resumen_en, descripcion_es, descripcion_en, destacado_es, destacado_en, exporta_desde, situacion, maquila, abv, productos, presentaciones_ml, contacto_email, contacto_tel, estatus, fuente)
values ('toke-innova', 'Toke Innova', null, 'puebla', 'Puebla', 'alimentos-procesados', 'Salsa macha, chimichurri, especias y productos artesanales de Puebla, 100% naturales, con venta en 12 estados de México y cuatro de Estados Unidos.', 'Artisanal salsa macha, chimichurri, spices and pantry products from Puebla — 100% natural, sold in 12 Mexican states and four US states.', 'Toke Innova, fundada en Puebla en 2017, elabora productos artesanales mexicanos 100% naturales bajo sus marcas La Artesanal Herencia Orza® y ¡Ay Buey!®. Empezó con su Salsa Macha y hoy su catálogo reúne 24 presentaciones: salsa macha en cuatro variedades, chimichurri, chiles y especias, miel, perlas de tapioca, crema de cacahuate y galletas.

Vende en 12 estados de México y en Estados Unidos, donde tiene presencia en California, Kansas, Oklahoma y Texas; sus etiquetas ya vienen en inglés y francés. Cuenta con registro ante COFEPRIS y la FDA. Sus productos tienen una vida de anaquel de 6 meses a 3 años y se surten en cajas de 8 a 52 piezas, según la presentación.', 'Toke Innova, founded in Puebla in 2017, makes 100% natural artisanal Mexican products under its La Artesanal Herencia Orza® and ¡Ay Buey!® brands. It started with its Salsa Macha and its catalogue now includes 24 products: salsa macha in four varieties, chimichurri, chillies and spices, honey, tapioca pearls, peanut butter and cookies.

It sells in 12 Mexican states and in the United States, with presence in California, Kansas, Oklahoma and Texas, and its labels are already in English and French. It is registered with COFEPRIS and the FDA. Shelf life ranges from 6 months to 3 years, and products ship in cases of 8 to 52 units depending on the item.', 'Vende en 4 estados de EUA', 'Sold in 4 US states', null, 'exportando', null, null, array['Salsa Macha 4 chiles y 6 semillas · 200 g', 'Salsa Macha 3 chiles y 3 semillas · 80 g', 'Salsa Macha de cacahuate con chile morita · 200 g y 80 g', 'Salsa Macha de miel de abeja y arándanos · 200 g y 80 g', 'Salsa No Tan Macha · 200 g y 80 g', 'Chimichurri · 200 g y 80 g', 'Chimichurri picoso · 80 g', 'Chile quebrado · 150 g', 'Pimienta de cayena · 60 g', 'Paprika · 60 g', 'Ajonjolí negro · 75 g', 'Miel pura de abeja · 100 g', 'Perlas de miel con propóleo · 80 g', 'Perlas de tapioca · 250 g y 500 g', 'Crema de cacahuate · 340 g', 'Galletas artesanales (nuez con amaranto, arándanos, avena, avellana) · 100 g']::text[], '{}'::integer[], 'aortiz.ventas@tokeinnova.com', '+52 222 801 7636', 'borrador', 'Directorio de Socios COMCE Sur 2026')
on conflict (slug) do nothing;
insert into empresa_mercados (empresa_id, pais) select id, 'estados-unidos' from empresas where slug = 'toke-innova' on conflict do nothing;
insert into empresa_certificaciones (empresa_id, certificacion) select id, 'fda' from empresas where slug = 'toke-innova' on conflict do nothing;
insert into empresa_certificaciones (empresa_id, certificacion) select id, 'cofepris' from empresas where slug = 'toke-innova' on conflict do nothing;

